//#region src/paths/Scim/ResourceTypes/index.ts
var Index = class {
	rc;
	_parent;
	type;
	constructor(_parent, type = null) {
		this._parent = _parent;
		this.rc = _parent.rc;
		this.type = type;
	}
	path(withParameter = true) {
		if (withParameter && this.type !== null) return `${this._parent.path()}/ResourceTypes/${this.type}`;
		return `${this._parent.path()}/ResourceTypes`;
	}
	/**
	* Returns the list of supported SCIM resource types
	* HTTP Method: get
	* Endpoint: /scim/{version}/ResourceTypes
	* Rate Limit Group: Light
	* App Permission: ReadAccounts
	*/
	async list(restRequestConfig) {
		return (await this.rc.get(this.path(false), void 0, restRequestConfig)).data;
	}
	/**
	* Returns resource type by ID
	* HTTP Method: get
	* Endpoint: /scim/{version}/ResourceTypes/{type}
	* Rate Limit Group: Light
	* App Permission: ReadAccounts
	*/
	async get(restRequestConfig) {
		if (this.type === null) throw new Error("type must be specified.");
		return (await this.rc.get(this.path(), void 0, restRequestConfig)).data;
	}
};
//#endregion
export { Index as default };
