import { Button, Form, Input, Tabs, Typography } from "antd";
import { auto } from "manate/react";

import type { Store } from "../store";

const { Text } = Typography;

const Login = auto((props: { store: Store }) => {
  const { store } = props;
  return (
    <Form labelCol={{ span: 8 }} wrapperCol={{ span: 8 }}>
      <Form.Item label="Server" required>
        <Input
          onChange={(e) => {
            store.server = e.target.value;
          }}
          value={store.server}
        />
      </Form.Item>
      <Form.Item
        label="Client ID"
        required
        extra="Required scopes: VoipCalling and ReadAccounts."
      >
        <Input
          onChange={(e) => {
            store.clientId = e.target.value;
          }}
          value={store.clientId}
          autoComplete="username"
        />
      </Form.Item>
      <Form.Item
        label="Device Serial"
        extra="Optional beta feature. Leave blank unless instructed."
      >
        <Input
          onChange={(e) => {
            store.deviceSerial = e.target.value;
          }}
          value={store.deviceSerial}
        />
      </Form.Item>
      <Tabs
        centered
        items={[
          {
            key: "auth-code",
            label: "Auth Code Flow",
            children: (
              <>
                <Form.Item wrapperCol={{ offset: 8, span: 16 }}>
                  <Text type="secondary">
                    Note: Set redirect URI to{" "}
                    {globalThis.location.origin + globalThis.location.pathname}
                    callback.html
                  </Text>
                </Form.Item>
                <Form.Item wrapperCol={{ offset: 8, span: 16 }}>
                  <Button type="primary" onClick={() => store.authCodeFlow()}>
                    Auth Code Flow
                  </Button>
                </Form.Item>
              </>
            ),
          },
          {
            key: "personal-jwt",
            label: "Personal JWT Flow",
            children: (
              <>
                <Form.Item label="Client Secret" required>
                  <Input.Password
                    onChange={(e) => {
                      store.clientSecret = e.target.value;
                    }}
                    value={store.clientSecret}
                    autoComplete="new-password"
                  />
                </Form.Item>
                <Form.Item label="JWT Token" required>
                  <Input.Password
                    onChange={(e) => {
                      store.jwtToken = e.target.value;
                    }}
                    value={store.jwtToken}
                    autoComplete="new-password"
                  />
                </Form.Item>
                <Form.Item wrapperCol={{ offset: 8, span: 16 }}>
                  <Button type="primary" onClick={() => store.jwtFlow()}>
                    Personal JWT Flow
                  </Button>
                </Form.Item>
              </>
            ),
          },
        ]}
      />
    </Form>
  );
});

export default Login;
