import SdkExtension from "@rc-ex/core/SdkExtension";
import URI from "urijs";
//#region src/index.ts
async function generateCodeVerifier() {
	const array = new Uint8Array(32);
	crypto.getRandomValues(array);
	return btoa(String.fromCharCode(...array)).replace(/\+/g, "-").replace(/\//g, "_").replace(/=/g, "");
}
async function generateCodeChallenge(verifier) {
	const data = new TextEncoder().encode(verifier);
	const hashBuffer = await crypto.subtle.digest("SHA-256", data);
	const hashArray = Array.from(new Uint8Array(hashBuffer));
	const hashStr = String.fromCharCode(...hashArray);
	return btoa(hashStr).replace(/\+/g, "-").replace(/\//g, "_").replace(/=/g, "");
}
var AuthorizeUriExtension = class extends SdkExtension {
	rc;
	codeVerifier;
	options;
	constructor(options = {}) {
		super();
		this.options = options;
	}
	async install(rc) {
		this.rc = rc;
	}
	async buildUri(_authorizeRequest) {
		const authorizeRequest = _authorizeRequest;
		if (!authorizeRequest.response_type) authorizeRequest.response_type = "code";
		if (!authorizeRequest.client_id) authorizeRequest.client_id = this.rc.rest.clientId;
		if (authorizeRequest.code_challenge_method === "S256") {
			this.codeVerifier = await generateCodeVerifier();
			authorizeRequest.code_challenge = await generateCodeChallenge(this.codeVerifier);
		}
		let uri;
		if (this.options.baseUri) uri = new URI(this.options.baseUri);
		else uri = new URI(this.rc.rest.server).directory("/restapi/oauth/authorize");
		return uri.search(authorizeRequest).toString();
	}
	async revoke() {}
};
//#endregion
export { AuthorizeUriExtension as default };
