//#region src/paths/Scim/Schemas/index.ts
var Index = class {
	rc;
	_parent;
	uri;
	constructor(_parent, uri = null) {
		this._parent = _parent;
		this.rc = _parent.rc;
		this.uri = uri;
	}
	path(withParameter = true) {
		if (withParameter && this.uri !== null) return `${this._parent.path()}/Schemas/${this.uri}`;
		return `${this._parent.path()}/Schemas`;
	}
	/**
	* Returns the list of schemas
	* HTTP Method: get
	* Endpoint: /scim/{version}/Schemas
	* Rate Limit Group: Light
	* App Permission: ReadAccounts
	*/
	async list(restRequestConfig) {
		return (await this.rc.get(this.path(false), void 0, restRequestConfig)).data;
	}
	/**
	* Returns SCIM schema
	* HTTP Method: get
	* Endpoint: /scim/{version}/Schemas/{uri}
	* Rate Limit Group: Light
	* App Permission: ReadAccounts
	*/
	async get(restRequestConfig) {
		if (this.uri === null) throw new Error("uri must be specified.");
		return (await this.rc.get(this.path(), void 0, restRequestConfig)).data;
	}
};
//#endregion
export { Index as default };
